/**
 * shzStars.ts
 *
 * Typed transcription of the NAAP Circumstellar Habitable Zone Simulator's
 * 17-star, time-indexed stellar-evolution catalog. Vendored data — do not
 * hand-edit; regenerate from the decoded source if it ever changes.
 *
 * Source: ../Baseline/Astronomy/astro-simulations/circumstellar-habitable-zone-simulator/src/shzStars.js
 * (schema documented in .../scripts/shz_loader.py). That file decodes the
 * original zlib+AMF-encoded `shzStars.dat` — no re-decoding needed here.
 *
 * Units: `time` in millions of years (Myr) since zero-age main sequence; `mass` in solar
 * masses (M☉); `logLum`/`logRadius`/`logTemp` are log₁₀ of luminosity (L☉),
 * radius (R☉), and effective temperature (K). The catalog spans 17 stars from
 * 0.3 M☉ to 30 M☉.
 *
 * `epochsList` entries mark stellar-evolution transitions. `type` uses the
 * Hurley, Pols & Tout (2000, MNRAS 315, 543) "kw" stellar-type code — see
 * STAR_EPOCH_LABELS below. The Flash original (SHZSystemHistory.as,
 * MainTimeline.as) only ever labels epoch 0 (start), epoch 1 (end of main
 * sequence, whatever its type), and the final epoch (star's end state, by
 * type: 10-12 white dwarf, 13 neutron star, 14 black hole, 15 disrupted).
 */

export type StarEpoch = { readonly type: number; readonly time: number };

export type StarDataPoint = {
  readonly time: number;
  readonly mass: number;
  readonly logLum: number;
  readonly logRadius: number;
  readonly logTemp: number;
};

export type StarRecord = {
  readonly mass: number;
  readonly timespan: number;
  readonly maxMass: number;
  readonly minMass: number;
  readonly maxLogLum: number;
  readonly minLogLum: number;
  readonly maxLogRadius: number;
  readonly minLogRadius: number;
  readonly epochsList: readonly StarEpoch[];
  readonly dataTable: readonly StarDataPoint[];
};

/**
 * Labels for the Hurley-Pols-Tout "kw" stellar-type codes seen in this
 * catalog's epochsList. Codes 0-9 are evolutionary phases; 10+ are remnants.
 */
export const STAR_EPOCH_LABELS: Record<number, string> = {
  0: "Convective low-mass main-sequence star",
  1: "Main-sequence star",
  2: "Hertzsprung-gap star",
  3: "Red giant branch",
  4: "Core helium burning",
  5: "Early asymptotic giant branch",
  6: "Thermally pulsing asymptotic giant branch",
  7: "Naked helium main-sequence star",
  8: "Naked helium Hertzsprung-gap star",
  9: "Naked helium giant branch star",
  10: "Helium white dwarf",
  11: "Carbon-oxygen white dwarf",
  12: "Oxygen-neon white dwarf",
  13: "Neutron star",
  14: "Black hole",
  15: "Disrupted (massless remnant)",
};

/**
 * Compressed catalog: every 3rd dataTable sample kept (plus endpoints and
 * epoch times), numeric fields rounded to 3–4 decimals. Linear interpolation
 * in StarEvolution.sampleStar remains valid. Full-density source lives in
 * ../Baseline/Astronomy/astro-simulations/.../shzStars.js if regeneration is needed.
 */

